def parse_logfmt(line: str) -> dict[str, str | bool]:
    result: dict[str, str | bool] = {}
    i, n = 0, len(line)
    while i < n:
        if line[i] == " ":
            i += 1
            continue
        start = i
        while i < n and line[i] not in " =":
            i += 1
        key = line[start:i]
        if i >= n or line[i] == " ":
            result[key] = True
            continue
        i += 1  # skip "="
        if i < n and line[i] == '"':
            i += 1
            chars: list[str] = []
            while True:
                if i >= n:
                    raise ValueError(f"unterminated quoted value for {key!r}")
                ch = line[i]
                if ch == "\\" and i + 1 < n:
                    chars.append(line[i + 1])
                    i += 2
                elif ch == '"':
                    i += 1
                    break
                else:
                    chars.append(ch)
                    i += 1
            result[key] = "".join(chars)
        else:
            start = i
            while i < n and line[i] != " ":
                i += 1
            result[key] = line[start:i]
    return result
